styles:
.page-post { --post-w: 720px; }
.page-post .post { padding-top: clamp(120px, 16vh, 190px); padding-bottom: clamp(48px, 7vw, 96px); }
.page-post .post__wrap { width: 100%; max-width: var(--post-w); margin-inline: auto; padding-inline: var(--gutter); }
.page-post .post__eyebrow { margin-bottom: 18px; }
.page-post .post__title {
  font-size: clamp(30px, 4.6vw, 54px);
  line-height: 1.14; letter-spacing: -0.01em; color: var(--grey-700);
}
.page-post .post__meta {
  display: flex; flex-wrap: wrap; align-items: center; gap: 10px;
  margin-top: clamp(20px, 3vw, 30px);
  font-size: clamp(14px, 1vw, 16px); color: var(--grey-500);
}
.page-post .post__meta .who { color: var(--grey-900); }
.page-post .post__meta .dot { color: var(--grey-300); }
.page-post .post__cover {
  max-width: 900px; margin: clamp(32px, 5vw, 60px) auto 0;
  padding-inline: var(--gutter);
}
.page-post .post__cover img {
  width: 100%; height: auto; border-radius: var(--radius-lg);
  background: var(--bg-alt);
}
.page-post .post__body { margin-top: clamp(40px, 6vw, 72px); }
.page-post .post__body p {
  font-size: clamp(17px, 1.25vw, 19px); line-height: 1.95;
  color: var(--grey-700); margin-bottom: 1.5em;
}
.page-post .post__body p.lead {
  font-size: clamp(18px, 1.4vw, 21px); line-height: 1.8;
  color: var(--grey-900);
}
.page-post .post__body strong { color: var(--grey-900); font-weight: 400; }
.page-post .post__foot {
  max-width: var(--post-w); margin: clamp(48px, 6vw, 80px) auto 0;
  padding: clamp(28px, 3vw, 40px) var(--gutter) 0; border-top: 1px solid var(--line);
}
.page-post .post__back {
  display: inline-flex; align-items: center; gap: 12px;
  font-size: 17px; color: var(--grey-900);
  transition: color .25s var(--ease), gap .25s var(--ease);
}
.page-post .post__back .arrow {
  width: 34px; height: 34px; border-radius: 50%;
  border: 1.5px solid var(--red); color: var(--red);
  display: grid; place-items: center; transition: background .3s var(--ease), color .3s var(--ease);
}
.page-post .post__back:hover { color: var(--red); gap: 16px; }
.page-post .post__back:hover .arrow { background: var(--red); color: #fff; }
